#include <iostream>

int main() {
    int a = 0;
    int b = 0;

    // Đọc hai số nguyên từ luồng nhập chuẩn
    if (std::cin >> a >> b) {
        // Đọc không phá hủy giá trị của a và b để tính tổng
        int sum = a + b;

        // Ghi đè có tính phá hủy lên biến a
        a = sum;

        std::cout << "Updated a: " << a << "\n";
        std::cout << "Preserved b: " << b << "\n";
    }

    return 0;
}

#include <iostream>

int main() {
    int x = 0;
    int y = 0;
    int z = 0;

    // Nhập ba số nguyên
    if (std::cin >> x >> y >> z) {
        // Tính tích ba số (bài tập 2.4 / 2.5)
        int product = x * y * z;
        std::cout << "The product is " << product << "\n";

        // Minh họa độ ưu tiên: nhân và chia trước, cộng sau
        int expr = x + y * z;
        std::cout << "Expression result: " << expr << "\n";

        // Minh họa điều kiện if đúng chuẩn
        if (product >= 100) {
            std::cout << "Product is greater than or equal to 100\n";
        }
        if (product != 7) {
            std::cout << "The product is not equal to 7\n";
        }
    }

    return 0;
}
